<?php
namespace App\Jobs;use App\Models\MediaAsset;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};
class ReprocessStudioWatermarks implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function __construct(public int$ownerId,public int$version){$this->onQueue('media-default');}public function handle():void{MediaAsset::where('owner_id',$this->ownerId)->whereHas('group',fn($q)=>$q->where('watermark_enabled',true))->whereHas('variants',fn($q)=>$q->where('variant_type','optimized')->where('state','ready'))->chunkById(100,function($assets){foreach($assets as$a){$a->variants()->where('variant_type','watermarked')->where('version','<',$this->version)->where('state','ready')->update(['state'=>'stale']);GenerateWatermarkedVariant::dispatch($a->id,$this->version);}});}}
